      }
    ],
    "dependent_passages": [
      {
        "reason": "После возможного удаления предпоследнего высказывания начало финала может потребовать короткой связки с ограничением подземной версии.",
        "anchors": [
          {
            "utterance_index": 21,
            "quote": "Снятая ручка стала самым заметным предметом этой истории."
          }
        ]
      }
    ]
  }
